section_3306_c_5_family_employment_exclu.procedure:
def apply(inputs, premises):
    employer = inputs["employer"]
    employee = inputs["employee"]
    relations = inputs["case_family_relations"]
    applies = False
    for relation in relations:
        if len(relation) == 3:
            owner = relation[0]
            word = relation[1]
            relative = relation[2]
            if owner == employee and relative == employer and word in premises["employee_has_employer_as_relative_words"]:
                applies = True
            if owner == employer and relative == employee and word in premises["employer_has_employee_as_relative_words"]:
                applies = True
    if applies:
        answer = "Entailment"
    else:
        answer = "Contradiction"
    return {"answer": answer}
